head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ172M01';

/* 최상단의 선언 */
scwin.isMain = function() {
	return true;
}

/**
 * onpageLoad시 경매용어 전체 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {

	scwin.lgnMbr = WebSquare.cookie.getCookie('cortAuctnLgnMbr')
	scglblo.setScUserId(scwin.lgnMbr);
	scscrno.setScPgmId(scwin.pgmId);

	/* 메뉴 */
	if(!scutilo.isEmpty(scwin.pgmId)){
	   $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId.slice(0,6));
	}

	dma_srchAuctnTrm.set("srchDvsCd","00");

	const comParam = com.storage.get('PGJ172M01','param') || '';
	if (!scutilo.isEmpty(comParam)) {
		dma_srchAuctnTrm.set("srchDvsCd","01");
		dma_srchAuctnTrm.set("srch",comParam);
		com.storage.removeSection("PGJ172M01");
	}
		com.executeSubmission(sbm_auctnTrmSrch);
};


scwin.onpageunload = function() {

};

/**
 * 경매용어 전체 데이터 받아온뒤 동적으로 컴포넌트 생성 후 값 입력
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */

/* 동적으로 생성한 컴포넌트 ID 중복 제거 */


scwin.sbm_auctnTrmSrch_submitdone = function(e) {
	ibx_auctnTrmSrch.focus();
	ibx_auctnTrmSrch.setValue(dma_srchAuctnTrm.get('srch'))
	if($p.getComponentById("grp_auctnTrmBox")!=null){
		grp_auctnTrmBox.remove();
	}
	$p.dynamicCreate("grp_auctnTrmBox", "group", {
		className : "term_list",
		tagname : "ul"
	}, grp_termBox)
	if (dlt_allAuctnTrmList.getTotalRow()>0) {

	/* 동적으로 컴포넌트 생성 */
		for(var i=0; i<dlt_allAuctnTrmList.getTotalRow(); i++){
			$p.dynamicCreate("grp_auctnTrm"+i, "group", {
				tagname : "li"
			}, grp_auctnTrmBox)

			var tempComponent = $p.getComponentById("grp_auctnTrm"+i);

			$p.dynamicCreate("tbx_auctnTrmTit"+i, "textbox", {
				className : "tit",
				label : dlt_allAuctnTrmList.getCellData(i, "ntatcTitlNm")
			}, tempComponent)

			$p.dynamicCreate("grp_auctnTrmCtt"+i, "group",{
				className : "cont"
			},tempComponent)

			var tempComponent2 = $p.getComponentById("grp_auctnTrmCtt"+i);

			$p.dynamicCreate("tbx_auctnTrmCtt"+i, "textbox", {
				label : dlt_allAuctnTrmList.getCellData(i, "ntatcCtxtCtt")
			}, tempComponent2)

		}
	} else {
		/* 현재 TO-BE 이미지가 없어서 AS-IS 이미지로 대체 나중에 교체 해야됨  TO-DO */
		$p.dynamicCreate("img_noneSrch", "image", {
			src:"/pgj/cm/images/dummy/ic_res_none.gif",
			style:"position:absolute; right:30%; width:35%;"
		}, grp_auctnTrmBox)
	}

};

/**
 * 검색어로 경매용어 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_auctnTrmSrch_onclick = function(e) {
	/* 검색어 앞뒤 공백제거 */
	let srchNm = scutilo.skipSpaces(ibx_auctnTrmSrch.getValue());
	if (srchNm.length == 1) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ. W_0009,"검색어"));
		return
	} else if(srchNm.length >= 2 && pgjUtil.spcCharChk2(srchNm)){
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0020));
		return
	} else {
		dma_srchAuctnTrm.set("srch", srchNm)
		dma_srchAuctnTrm.set("srchDvsCd","01");
		com.executeSubmission(sbm_auctnTrmSrch)

	}
};

/**
 * 엔터 눌렀을 시 검색어로 경매용어 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.12.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_auctnTrmSrch_onkeydown = function(e) {
	if(e.code == "Enter") {
		scwin.btn_auctnTrmSrch_onclick()
	}
};

/**
 * 전체 버튼 클릭시 경매용어 전체조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.anc_allInq_onclick = function() {
	scwin.onpageload();
};



/**
 * " ㄱ, ㄴ, ㄷ " 등 버튼 클릭시 경매용어 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.anc_srchwd_onclick = function() {
	/* 자음 클릭시 검색어 초기화 */
	ibx_auctnTrmSrch.setValue("");

	var data = this.getUserData("userData1");
	dma_srchAuctnTrm.set("srchDvsCd","02");
	dma_srchAuctnTrm.set("cortAuctnRletDvsCd",data);
	com.executeSubmission(sbm_auctnTrmSrch);
};

/**
 * 인기검색어 버튼 클릭시 경매용어 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.anc_popltSrchwd_onclick = function(){
	var popltData = this.getUserData("userData1");
	ibx_auctnTrmSrch.setValue(popltData);
	scwin.btn_auctnTrmSrch_onclick();
}

/**
 * 특수문자 입력을 막아준다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.12.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_auctnTrmSrch_onkeypress = function(e) {
	pgjUtil.noneInputSpcChar(e)
};
